#!/usr/bin/env python3
"""Promote the index-5/2 Lane–Emden headline, its simulator, certificates and existence proof from
Work/Math to Checked/Math (run 2026-11-19T1628Z; promote_le32.py of run 2026-11-19T1028Z with the index changed; LEGStart is already in Checked).

Mechanical copy: namespaces Work.Math -> Checked.Math, `import Mathlib` -> specific modules, module docs
replaced by number-free text (check_prose rule 7). Statements and proofs otherwise byte-identical."""
import pathlib
ROOT = pathlib.Path(__file__).resolve().parents[3]
W, C = ROOT / "Work/Math", ROOT / "Checked/Math"
MODS = ["LE52Cell", "LE52CellQ", "LE52Glue", "LE52QData", "LE52Chain", "LaneEmden52",
        "LE52ExistsLeft", "LE52ExistsRight", "LE52Exists"]
G = "`runs/2026-11-19T1628Z/scripts/emit_le52.py`"
P = "Promoted verbatim from `Work/Math/{m}.lean`."
DOCS = {
 "LE52Cell": "Lane–Emden equation of index five halves: the nonlinearity θ to the power five halves as `g52 θ`, the fifth power of the square root (equal to Mathlib's real power for every real θ, `rpow52_eq`), its Lipschitz bound on a slab (`g52_lip`), the closeness of `g52 x` to the fifth power of `y` from a certificate that the square of `y` is close to `x` (`g52_close`), and the validated cell step `cell` (Grönwall, generic tube lemma `Checked.Math.LENCell.tube_cell_t`).",
 "LE52CellQ": "Lane–Emden equation of index five halves: the validated cells of `Checked.Math.LE52Cell.cell` checked by kernel evaluation. All side conditions and both defect bounds of a cell are one proposition over the rationals (`CellProp`); the power of the Taylor polynomial is replaced in the defect by the fifth power of a polynomial `pw` whose square is certified close to it and which is bounded away from zero, and in a cell next to the zero of θ (`pw` empty) it is bounded crudely. The chain lemmas are those of `Checked.Math.LENCellQ` with this field.",
 "LE52Glue": "Lane–Emden equation of index five halves: the singular start (`start52`, the generic start of `Checked.Math.LEGStart` with a residual certified through the square-root polynomial) and the last cell (`last52`: sign change of θ, φ negative, bounds on the mass factor), each from one proposition over the rationals decided by kernel evaluation; `qeqB` compares coefficient lists with order relations only.",
 "LE52QData": f"Generated by {G}: the singular start and the validated cells of the Lane–Emden chain of index five halves as data; every side condition, defect bound and link decided by kernel evaluation over the rationals, one declaration per segment of cells.",
 "LE52Chain": f"Generated by {G}: chaining of the singular start, the kernel-checked segments and the last cell of the Lane–Emden chain of index five halves.",
 "LE52ExistsLeft": "Lane–Emden equation of index five halves, existence near the centre: Banach fixed point of the scaled Volterra map with the clamped power five halves (the index-three construction `Checked.Math.LEExistsLeft`, whose constants bound this power too).",
 "LE52ExistsRight": "Lane–Emden equation of index five halves, existence away from the centre: Picard–Lindelöf for the clamped field; the clamped energy is nonincreasing and the potential part is not negative, so the clamp on φ stays inactive, and the bound on θ' keeps the clamp on θ inactive (adapted from `Checked.Math.LEExistsRight`).",
 "LE52Exists": "Lane–Emden equation of index five halves: existence of a solution meeting every hypothesis of `Checked.Math.LaneEmden52.laneEmden52_constants` (left piece by a fixed point, right piece by Picard–Lindelöf for the clamped field with the clamps inactive by the energy, glued).",
}
for m in MODS:
    s = (W / f"{m}.lean").read_text()
    s = s.replace("Work.Math.", "Checked.Math.")
    assert "Work." not in s, m
    if m == "LaneEmden52":
        s = s.replace("import Mathlib\n", "import Mathlib.Analysis.Calculus.Deriv.MeanValue\nimport Mathlib.Topology.Order.IntermediateValue\n", 1)
        s = s.replace("frozen before proof, run 2026-11-19T1628Z", "frozen before proof in `Work/Math/LaneEmden52.lean`, statement promoted\nbyte-identical")
        s = s.replace("Existence of such a θ is a separate theorem (to do).",
                      "Existence of such a θ:\n`Checked.Math.LE52Exists.exists_solution` (non-vacuity witness in `Checked/Trust/Witnesses.lean`).")
        i = s.index("\n\n**Proof** (run"); j = s.index("-/", i)
        s = s[:i] + "\n" + s[j:]
        assert "to do" not in s
    else:
        assert "import Mathlib\n" not in s, m
        i = s.index("/-!")
        j = s.index("-/", i) + 2
        s = s[:i] + "/-! " + DOCS[m] + " " + P.format(m=m) + " -/" + s[j:]
    (C / f"{m}.lean").write_text(s)
    print("wrote", m)
